import {openActions} from './select-choice';
import {test,expect,type Page,type APIResponse} from '@playwright/test';
import {randomBytes,randomUUID,createHash} from 'node:crypto';
import {readFileSync} from 'node:fs';
import dotenv from 'dotenv';
import pg from 'pg';
import sharp from 'sharp';
import {chooseOption} from './select-choice';

const config=dotenv.parse(readFileSync('.env')),headers={origin:'http://127.0.0.1:18186'};
async function data(r:APIResponse,status=200){expect(r.status()).toBe(status);return (await r.json()).data;}
async function seed(page:Page,studioName='界面验收工作室'){const tag=randomBytes(6).toString('hex'),slug='feedback-'+tag,s=await data(await page.request.post('/api/v1/auth/register',{headers,data:{username:'feedback_'+tag,email:'feedback-'+tag+'@example.test',name:'界面验收摄影师',password:'Local-Feedback!5291',studioName,slug}}));const sid=s.studioId as string;const profile=await data(await page.request.get(`/api/v1/studios/${sid}/config/profile`));await data(await page.request.put(`/api/v1/studios/${sid}/config/profile`,{headers,data:{version:profile.version,value:{...profile.value,wechat:'feedback-studio'}}}));return {sid,slug};}
async function project(page:Page,sid:string){const created=await data(await page.request.post(`/api/v1/studios/${sid}/projects`,{headers,data:{key:randomUUID(),name:'界面客户',wechat:'client-copy-only',phoneLast4:'',pin:'4826',title:'界面交互验收项目',packageSource:'custom',packageId:null,contentVersion:1,quota:2,price:'',special:'',dateFlexible:true,intendedDate:'',slotId:null,slotVersion:null}}));return data(await page.request.get(`/api/v1/studios/${sid}/projects/${created.id}`));}
async function fit(page:Page){for(const width of [320,390,393,1280]){await page.setViewportSize({width,height:852});expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(width);}}
async function separated(page:Page,first:import('@playwright/test').Locator,second:import('@playwright/test').Locator){for(const width of [320,390,393,1280]){await page.setViewportSize({width,height:852});await expect(first).toBeVisible();await expect(second).toBeVisible();const a=(await first.boundingBox())!,b=(await second.boundingBox())!;expect(b.y-a.y-a.height,`independent modules have breathing room at ${width}`).toBeGreaterThanOrEqual(16);expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(width);}}
async function pullPage(page:Page,selector='#main'){await page.evaluate(sel=>{window.scrollTo({top:0,behavior:'instant'});const el=document.querySelector(sel)!;const a=new Touch({identifier:1,target:el,clientX:20,clientY:40}),b=new Touch({identifier:1,target:el,clientX:20,clientY:200});el.dispatchEvent(new TouchEvent('touchstart',{touches:[a],bubbles:true}));el.dispatchEvent(new TouchEvent('touchmove',{touches:[b],bubbles:true,cancelable:true}));el.dispatchEvent(new TouchEvent('touchend',{changedTouches:[b],bubbles:true}));},selector);}
test.beforeEach(async()=>{expect(new URL(config.TEST_MIGRATION_DATABASE_URL!).pathname).toBe('/proofroom_test');const db=new pg.Client({connectionString:config.TEST_MIGRATION_DATABASE_URL});await db.connect();try{await db.query("delete from rate_limits where key='register:127.0.0.1'");}finally{await db.end();}});

test('T079: project entry opens the pending task and keeps future bookings, cancellation and explicit deep links',async({page})=>{
 const s=await seed(page),p=await project(page,s.sid),base=`/api/v1/studios/${s.sid}/projects/${p.id}`;let current=p;await page.route('**'+base,route=>route.fulfill({json:{data:current,error:null}}));
 for(const [value,tab] of [[p,'原片'],[{...p,workflowStage:'P3'},'交付'],[{...p,booking:{startAt:new Date(Date.now()+86400000).toISOString()}},'概览'],[{...p,lifecycleStatus:'cancelled'},'概览']] as const){current=value;await page.goto(`/studio/projects/${p.id}?studio=${s.sid}`);await expect(page.locator('.project-tabs [aria-current=page]')).toHaveText(tab);}
 current=p;await page.goto(`/studio/projects/${p.id}?studio=${s.sid}&section=overview`);await expect(page.locator('.project-tabs [aria-current=page]')).toHaveText('概览');await page.reload();await expect(page.locator('.project-tabs [aria-current=page]')).toHaveText('概览');
});

test('T080: customer sees photos first on narrow screens and every auxiliary tool remains reachable',async({page})=>{
 const s=await seed(page),p=await project(page,s.sid),base=`/api/v1/studios/${s.sid}/projects/${p.id}`,file=await sharp({create:{width:80,height:60,channels:3,background:'orange'}}).jpeg().toBuffer(),batch=await data(await page.request.post(base+'/upload-batches',{headers,data:{key:randomUUID(),role:'original',files:[{filename:'first.jpg',bytes:file.length,sha256:createHash('sha256').update(file).digest('hex')}]}}));for(const item of batch.items)expect((await page.request.put(`${base}/upload-batches/${batch.id}/items/${item.id}/bytes`,{headers:{...headers,'content-type':'application/octet-stream','x-upload-grant':item.uploadGrant},data:file})).ok()).toBe(true);await expect.poll(async()=>(await data(await page.request.get(base+'/upload-batches/'+batch.id))).state).toBe('ready');const token=p.clientLink.split('/').pop();await data(await page.request.post(`/api/v1/client/${token}/pin`,{headers,data:{pin:'4826'}}));await page.route(`**/api/v1/client/${token}`,async route=>{const response=await route.fetch(),body=await response.json();body.data.project.title='很长的摄影项目名称'.repeat(10);await route.fulfill({response,json:body});});await page.goto(p.clientLink);await expect(page.locator('.project-photo')).toHaveCount(1);
 for(const width of [320,390,393,1280]){await page.setViewportSize({width,height:852});await expect(page.getByRole('button',{name:'导出已选CSV',exact:true})).toBeHidden();expect((await page.locator('.project-photo').first().boundingBox())!.y).toBeLessThan(650);expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(width);}
 await openActions(page.getByTitle('更多照片操作',{exact:true}));for(const label of ['切换列表','读取最新照片','搜索照片','导出已选CSV','复制已选文件名'])await expect(page.getByRole('button',{name:label,exact:true})).toBeVisible();await page.getByRole('button',{name:'展开完整名称',exact:true}).click();await expect(page.getByRole('button',{name:'收起名称',exact:true})).toBeVisible();
});

test('T081: customer download has one primary action, starts once, survives refresh and still checks authorization',async({page})=>{
 const s=await seed(page),p=await project(page,s.sid),token=p.clientLink.split('/').pop(),base=`/api/v1/client/${token}`,jid=randomUUID(),job={id:jid,kind:'all',state:'ready',version:1,error:null,bytes:11,manifestVersion:1,counts:{original:1,retouched:1},downloadUrl:`${base}/zips/${jid}/file`};let ready=false;const status=()=>({...job,state:ready?'ready':'processing',downloadUrl:ready?job.downloadUrl:null});await data(await page.request.post(base+'/pin',{headers,data:{pin:'4826'}}));
 // DTO/byte fixtures isolate the interaction; the delivery suite verifies real archives and source hashes.
 await page.route('**'+base,async route=>{const response=await route.fetch(),body=await response.json();body.data.project={...body.data.project,workflowStage:'P4',canEdit:false};await route.fulfill({response,json:body});});await page.route('**'+base+'/downloads',route=>route.fulfill({json:{data:{available:true,reason:'',expiresAt:new Date(Date.now()+86400000).toISOString(),manifestVersion:1,counts:{original:1,retouched:1},files:[]},error:null}}));await page.route('**'+base+'/zips',route=>route.fulfill({json:{data:status(),error:null}}));await page.route('**'+base+'/zips/'+jid,route=>route.fulfill({json:{data:status(),error:null}}));let blocked=false,downloads=0;page.on('download',()=>downloads++);await page.route('**'+job.downloadUrl,route=>route.fulfill(blocked?{status:403}:{headers:{'content-type':'application/zip','content-disposition':'attachment; filename=ui-fixture.zip'},body:Buffer.from('zip fixture')}));await page.goto(p.clientLink);const primary=page.getByRole('button',{name:'下载全部照片',exact:true});await expect(primary).toHaveCount(1);expect((await page.locator('.customer-download-main').boundingBox())!.y).toBeLessThan((await page.locator('.download-policy').boundingBox())!.y);await expect(page.getByRole('button',{name:'准备全部原片ZIP',exact:true})).toBeHidden();const received=page.waitForEvent('download');await primary.click();await expect(page.getByText('正在准备下载…',{exact:true})).toBeVisible();await expect(page.locator('.zip-card').getByRole('button',{name:/^刷新/})).toHaveCount(0);ready=true;/* 手动刷新下载状态的入口已随下拉刷新下线，就绪靠 ZipCard 的 1400ms 轮询自动接管。 */expect(new URL((await received).url()).pathname.endsWith('/file')).toBe(true);await page.reload();await page.waitForLoadState('networkidle');await expect(primary).toBeVisible();expect(downloads).toBe(1);blocked=true;await primary.click();await expect(page.locator('.zip-card').getByRole('alert')).toContainText('DOWNLOAD_UNAVAILABLE');expect(downloads).toBe(1);await page.getByText('分开下载原片或精修',{exact:true}).click();await expect(page.getByRole('button',{name:'准备全部原片ZIP',exact:true})).toBeVisible();await expect(page.getByRole('button',{name:'准备全部精修ZIP',exact:true})).toBeVisible();
});

