 await nav.getByRole('button',{name:'工作台',exact:true}).click();await expect(page.locator('.status-card').first()).toHaveAccessibleDescription('共2个');await page.route(`**/studios/${s.sid}/dashboard`,route=>route.fulfill({status:503,json:{data:null,error:{code:'TEMPORARY_UNAVAILABLE',message:'数量暂不可用'}}}));await pullPage(page,'.status-cards');await expect(page.locator('.notice.error[role=alert]')).toContainText('数量暂不可用');await expect(page.locator('.dashboard-actions')).toHaveCount(0);await expect(page.locator('.status-cards')).toHaveCount(0);await expect(nav.locator('.count-badge')).toHaveCount(0);
