test('T108: closed consultations keep work categories, photo preview and long FAQ readable',async({page})=>{const s=await seed(page);await page.route(`**/api/v1/public/${s.slug}/config`,async route=>{const r=await route.fetch(),body=await r.json();body.data.canSubmit=false;body.data.unavailableReason='暂不接收新咨询';body.data.content.value.faq=[{id:'closed-faq',question:'如何准备拍摄？',answer:'请与摄影师确认细节。'.repeat(30)}];await route.fulfill({response:r,json:body});});await page.goto('/t/'+s.slug);await expect(page.getByRole('button',{name:'提交拍摄咨询',exact:true})).toBeDisabled();await page.getByRole('tab',{name:'情侣',exact:true}).click();await expect(page.getByRole('tab',{name:'情侣',exact:true})).toHaveAttribute('aria-selected','true');await page.getByRole('tab',{name:'全部',exact:true}).click();await page.locator('#portfolio .image-button').first().click();await expect(page.getByRole('dialog')).toBeVisible();await page.keyboard.press('Escape');await expect(page.getByRole('dialog')).toHaveCount(0);await page.getByRole('button',{name:'展开完整答案',exact:true}).click();await expect(page.getByRole('button',{name:'收起',exact:true})).toBeVisible();});


test('T110: public refresh applies new unedited content and submission availability, while changed questions preserve dirty answers until review',async({page,browser})=>{
 const s=await seed(page),profile=await data(await page.request.get(`/api/v1/studios/${s.sid}/config/profile`));await data(await page.request.put(`/api/v1/studios/${s.sid}/config/profile`,{headers,data:{version:profile.version,value:{...profile.value,wechat:''}}}));const guest=await browser.newContext({baseURL:headers.origin}),customer=await guest.newPage();try{await customer.goto('/t/'+s.slug);await expect(customer.getByRole('button',{name:'提交拍摄咨询',exact:true})).toBeDisabled();const now=await data(await page.request.get(`/api/v1/studios/${s.sid}/config/profile`));await data(await page.request.put(`/api/v1/studios/${s.sid}/config/profile`,{headers,data:{version:now.version,value:{...now.value,wechat:'open-again'}}}));const content=await data(await page.request.get(`/api/v1/studios/${s.sid}/config/content`));await data(await page.request.put(`/api/v1/studios/${s.sid}/config/content`,{headers,data:{version:content.version,value:{...content.value,faq:[{id:'fresh',question:'新增问题',answer:'刷新后应可见的答案'}]}}}));await pullPage(customer);await expect(customer.locator('.page-refresh-feedback')).toHaveAttribute('data-state','done');await expect(customer.getByRole('button',{name:'提交拍摄咨询',exact:true})).toBeEnabled();await expect(customer.locator('.public-faq')).toContainText('刷新后应可见的答案');await customer.getByLabel('怎么称呼你？ *',{exact:true}).fill('  不要覆盖的客户  ');await customer.getByLabel('项目访问码（四位数字）',{exact:true}).fill('4826');const q=await data(await page.request.get(`/api/v1/studios/${s.sid}/config/questionnaire`));await data(await page.request.put(`/api/v1/studios/${s.sid}/config/questionnaire`,{headers,data:{version:q.version,value:{questions:q.value.questions.map((v:any)=>v.id==='q2'?{...v,options:['家庭','其他']}:v)}}}));await pullPage(customer);await expect(customer.getByRole('button',{name:'保留填写并核对更新',exact:true})).toBeVisible();await expect(customer.getByLabel('怎么称呼你？ *',{exact:true})).toHaveValue('  不要覆盖的客户  ');await expect(customer.getByLabel('项目访问码（四位数字）',{exact:true})).toHaveValue('4826');await customer.getByRole('button',{name:'保留填写并核对更新',exact:true}).click();await customer.getByRole('button',{name:'沿用兼容答案，重新确认变动项',exact:true}).click();await expect(customer.getByLabel('怎么称呼你？ *',{exact:true})).toHaveValue('  不要覆盖的客户  ');await expect(customer.getByLabel('项目访问码（四位数字）',{exact:true})).toHaveValue('');}finally{await guest.close();}
});

test('T107: the disappearing right arrow keeps keyboard focus in the rail without changing the selected category',async({page})=>{const s=await seed(page);await page.setViewportSize({width:320,height:700});await page.goto('/t/'+s.slug);await page.emulateMedia({reducedMotion:'reduce'});const rail=page.locator('[data-rail-label="作品分组"]'),arrow=rail.getByRole('button',{name:'向右查看作品分组',exact:true});await expect(arrow).toBeVisible();for(let i=0;i<12&&await arrow.count();i++){await arrow.focus();await page.keyboard.press('Enter');await page.waitForTimeout(40);}await expect(arrow).toHaveCount(0);expect(await rail.evaluate(el=>el.contains(document.activeElement))).toBe(true);await expect(page.getByRole('tab',{name:'全部',exact:true})).toHaveAttribute('aria-selected','true');await page.keyboard.press('Enter');await expect(page.getByRole('tab',{name:'商业形象',exact:true})).toHaveAttribute('aria-selected','true');});


test('T110: a short pull bounces back without requesting data and reduced motion settles immediately',async({page})=>{const s=await seed(page);await page.goto('/studio?studio='+s.sid);await expect(page.locator('.status-card')).toHaveCount(4);let reads=0;page.on('request',r=>{if(r.method()==='GET'&&r.url().includes('/api/v1/'))reads++;});for(const reduced of [false,true]){await page.emulateMedia({reducedMotion:reduced?'reduce':'no-preference'});const result=await page.evaluate(()=>{window.scrollTo({top:0,behavior:'instant'});const el=document.querySelector<HTMLElement>('#main')!,start=new Touch({identifier:1,target:el,clientX:20,clientY:40}),end=new Touch({identifier:1,target:el,clientX:20,clientY:100});el.dispatchEvent(new TouchEvent('touchstart',{touches:[start],bubbles:true}));el.dispatchEvent(new TouchEvent('touchmove',{touches:[end],bubbles:true,cancelable:true}));el.dispatchEvent(new TouchEvent('touchend',{changedTouches:[end],bubbles:true}));return {animations:el.getAnimations().length};});expect(result.animations).toBe(reduced?0:1);await expect.poll(()=>page.locator('#main').evaluate(el=>el.getAnimations().length)).toBe(0);}expect(reads).toBe(0);});


test('T143: empty submission explains every required field in plain words and keeps each hint under its own field',async({page})=>{
 test.setTimeout(120000);const s=await seed(page);
 for(const width of [390,1440]){
  await page.setViewportSize({width,height:900});await page.goto('/t/'+s.slug);
  await page.getByRole('button',{name:'提交拍摄咨询',exact:true}).click();
  await expect(page.getByText('请填写你的称呼',{exact:true})).toBeVisible();
  await expect(page.getByText('请选择「想拍什么类型的照片」',{exact:true})).toBeVisible();
  await expect(page.getByText('请填写你的微信号，方便摄影师联系你',{exact:true})).toBeVisible();
  await expect(page.getByText('请填写 4 位数字访问码',{exact:true})).toBeVisible();
  await expect(page.locator('.field-error:empty'),`${width} 未出错的项目不该渲染空提示节点`).toHaveCount(0);
  const order=await page.evaluate(()=>{
   const hint=[...document.querySelectorAll('.public-question p.hint')].find(p=>p.textContent?.includes('微信用于沟通'));
   const pin=[...document.querySelectorAll('.public-question label')].find(l=>l.textContent?.includes('项目访问码'));
   const wechat=document.querySelector('input[aria-label="你的微信号"]');
   if(!hint||!pin||!wechat)return null;
   const follows=(a:Element,b:Element)=>(a.compareDocumentPosition(b)&Node.DOCUMENT_POSITION_FOLLOWING)!==0;
   return {hintAfterWechat:follows(wechat,hint),hintBeforePin:follows(hint,pin)};
  });
  expect(order,`${width} 联系方式说明应紧跟微信号输入框`).toEqual({hintAfterWechat:true,hintBeforePin:true});
 }
});

test('T144: card copy never touches the first field of the form that follows it',async({page})=>{
 const s=await seed(page);
 await page.goto(`/studio/account?studio=${s.sid}`);
 const card=page.locator('section.card-pad').filter({hasText:'修改密码'});
 const note=card.locator('p').first(),label=card.getByText('原密码',{exact:true});
 await expect(label).toBeVisible();
 for(const width of [390,1280]){
  await page.setViewportSize({width,height:900});
  const a=(await note.boundingBox())!,b=(await label.boundingBox())!;
  expect(b.y-(a.y+a.height),`${width} 说明与首个字段之间应有呼吸空间`).toBeGreaterThanOrEqual(12);
 }
});

test('T145: 手机端保存条完整露出，不被底部导航与凸起的「新建」按钮压住',async({page})=>{
 const s=await seed(page);
 await page.setViewportSize({width:390,height:844});
 await page.goto(`/studio/portfolio?studio=${s.sid}`);
 const bar=page.locator('.save-bar').first();
 await expect(bar).toBeVisible();
 for(const y of [0,400,900]){
  await page.evaluate(v=>window.scrollTo(0,v),y);
  await page.waitForTimeout(150);
  const b=(await bar.boundingBox())!,n=(await page.locator('.mobile-nav').boundingBox())!;
  expect(b.y+b.height,`y=${y} 保存条下沿压到底部导航（含凸起的新建按钮）`).toBeLessThanOrEqual(n.y-24);
 }
});
